// Generates the demo hero banners (theme.config.ts `hero.slides`) as flat still-life illustrations, no third-party
// assets: one wide image (1920×800, desktop) and one tall image (840×1050, phones) per slide, into public/hero.
// Licence: CC0 — generated by this script, do whatever you like with them.
//   node seed/demo-hero.mjs
import { mkdirSync, writeFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"
import sharp from "sharp"

const out = join(dirname(fileURLToPath(import.meta.url)), "..", "public", "hero")
mkdirSync(out, { recursive: true })

const SIZES = { wide: [1920, 800], tall: [840, 1050] }

/** Scenes draw into a 1000×1000 box centred on the right half (wide) or the top (tall); the copy sits bottom-left */
const scenes = {
  "new-season": {
    bg: ["#EFE9E0", "#D9CFC2"],
    draw: (c1, c2, c3) => `
      <circle cx="560" cy="520" r="300" fill="${c1}"/><circle cx="560" cy="520" r="210" fill="none" stroke="#F3F0EA" stroke-opacity=".4" stroke-width="6"/>
      <circle cx="560" cy="520" r="120" fill="${c2}"/>
      <rect x="120" y="640" width="420" height="300" rx="20" fill="${c3}" transform="rotate(-8 330 790)"/>
      <rect x="820" y="330" width="60" height="460" rx="30" fill="${c2}" transform="rotate(14 850 560)"/>`,
  },
  makers: {
    bg: ["#E8E2D8", "#B9AD9D"],
    draw: (c1, c2, c3) => `
      <path d="M380 620 L500 300 h200 l120 320z" fill="${c1}"/><rect x="580" y="620" width="40" height="230" fill="${c2}"/>
      <rect x="470" y="850" width="260" height="46" rx="23" fill="${c2}"/>
      <rect x="120" y="760" width="760" height="40" rx="10" fill="${c3}"/>
      <circle cx="260" cy="650" r="70" fill="${c2}"/><circle cx="260" cy="650" r="36" fill="${c1}"/>`,
  },
  textiles: {
    bg: ["#ECE7DF", "#C9BFB1"],
    draw: (c1, c2, c3) => `
      <rect x="180" y="300" width="640" height="520" rx="34" fill="${c1}"/>
      <g stroke="#F3F0EA" stroke-opacity=".45" stroke-width="12">${[0, 1, 2, 3, 4].map((i) => `<line x1="180" y1="${380 + i * 90}" x2="820" y2="${380 + i * 90}"/>`).join("")}</g>
      <rect x="180" y="760" width="640" height="60" rx="30" fill="${c2}"/>
      <rect x="640" y="200" width="220" height="220" rx="24" fill="${c3}" transform="rotate(6 750 310)"/>`,
  },
}

const INK = ["#3A3632", "#6B645C", "#A89F93"]

function svg(name, shape) {
  const [w, h] = SIZES[shape]
  const { bg, draw } = scenes[name]
  // the scene box: right half on wide, upper part on tall; copy stays bottom-left, over the darker gradient edge
  const scale = shape === "wide" ? 0.78 : 0.84
  const tx = shape === "wide" ? w - 1000 * scale - 80 : (w - 1000 * scale) / 2
  const ty = shape === "wide" ? (h - 1000 * scale) / 2 : 40
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}">
    <defs>
      <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${bg[0]}"/><stop offset="1" stop-color="${bg[1]}"/></linearGradient>
    </defs>
    <rect width="${w}" height="${h}" fill="url(#bg)"/>
    <ellipse cx="${w * 0.5}" cy="${h * 0.95}" rx="${w * 0.45}" ry="${h * 0.06}" fill="#000" opacity=".06"/>
    <g transform="translate(${tx} ${ty}) scale(${scale})">${draw(...INK)}</g>
  </svg>`
}

for (const name of Object.keys(scenes)) {
  for (const shape of Object.keys(SIZES)) {
    const jpg = await sharp(Buffer.from(svg(name, shape))).jpeg({ quality: 80, mozjpeg: true, progressive: true }).toBuffer()
    writeFileSync(join(out, `${name}-${shape}.jpg`), jpg)
  }
}
console.log(`${Object.keys(scenes).length * 2} images → ${out}`)
